import * as M from "node:events";
function main(): void {
  const e: any = new M.EventEmitter();
  console.log(M.on.length, M.once.length, M.listenerCount.length, M.setMaxListeners.length, M.addAbortListener.length);
  console.log(typeof M.EventEmitter.init, Object.keys(e).join(","), e._eventsCount);
  e.on("a", () => {});
  e.on("b", () => {});
  console.log(e._eventsCount, M.listenerCount(e, "a"));
}
